var EFEMERIDES_TEXTOS = {"titulo_exacto": "<span class=\"i18n-es\">Un día como hoy</span><span class=\"i18n-en\">On this day</span><span class=\"i18n-fr\">Un jour comme aujourd'hui</span>", "titulo_cercano": "<span class=\"i18n-es\">Por estas fechas</span><span class=\"i18n-en\">Around this date</span><span class=\"i18n-fr\">À cette période</span>", "conector": "<span class=\"i18n-es\">ganó</span><span class=\"i18n-en\">won by</span><span class=\"i18n-fr\">victoire de</span>"};
(function () {
  var contenedor = document.getElementById('efemeride');
  if (!contenedor || typeof EFEMERIDES === 'undefined') return;
  var hoy = new Date();
  var desplazamientos = [0, -1, 1, -2, 2, -3, 3];
  for (var i = 0; i < desplazamientos.length; i++) {
    var dia = new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate() + desplazamientos[i]);
    var clave = ('0' + (dia.getMonth() + 1)).slice(-2) + '-' + ('0' + dia.getDate()).slice(-2);
    var entradas = EFEMERIDES[clave];
    if (!entradas) continue;
    var titulo = desplazamientos[i] === 0 ? EFEMERIDES_TEXTOS.titulo_exacto : EFEMERIDES_TEXTOS.titulo_cercano;
    var elementos = '';
    entradas.slice(0, 3).forEach(function (entrada) {
      var premio = EFEMERIDES_PREMIOS[entrada.premio];
      elementos += '<li>' + premio.bandera + entrada.fecha + ' &middot; <a href="' + entrada.url + '">' +
        premio.nombre + '</a> &mdash; ' + EFEMERIDES_TEXTOS.conector + ' ' + entrada.ganador +
        ' (' + entrada.equipo + ')</li>';
    });
    contenedor.innerHTML = '<h2>' + titulo + '</h2><ul>' + elementos + '</ul>';
    contenedor.hidden = false;
    return;
  }
})();
